/* Independently modelled from OSM/SMASH DATA and viewed OMA exterior photo.
 * Footprint is sourced. Core dimensions, vertical proportions and unseen faces are estimates. */
function prepareLandmarkGeometry(data){const b=data.buildings.find(b=>b.id==='252233408');if(!b)return;b.model='museum';const p=b.p,c=p.reduce((s,p)=>[s[0]+p[0]/4,s[1]+p[1]/4],[0,0]),len=Math.hypot(p[1][0]-p[0][0],p[1][1]-p[0][1]),u=[(p[1][0]-p[0][0])/len,(p[1][1]-p[0][1])/len],v=[-u[1],u[0]];b.collisionOutline=[[-7,-5],[7,-5],[7,5],[-7,5]].map(([a,d])=>[c[0]+u[0]*a+v[0]*d,c[1]+u[1]*a+v[1]*d]);b.modelNote='151동: OMA 사진 기반 캔틸레버·경사진 하부·중앙 코어. 수직 치수와 가려진 면은 추정.';}
function buildLandmark(B,scene,b,height){
 const V=(x,y,z)=>new B.Vector3(x,y,z),p=b.p,hs=p.map(p=>height(...p)),top=Math.max(...hs)+16,bottom=hs.map(h=>h+7),positions=[],indices=[],uvs=[];
 const material=new B.StandardMaterial('museum-silver',scene),texture=new B.DynamicTexture('museum-panels',{width:512,height:256},scene,true),c=texture.getContext();c.fillStyle='#aabec2';c.fillRect(0,0,512,256);for(let x=0;x<512;x+=7){c.fillStyle=x%21?'#8c9fa5':'#c6d2ce';c.fillRect(x,0,2,256)}c.strokeStyle='#dae0d8';c.lineWidth=7;c.beginPath();c.moveTo(0,128);c.lineTo(512,128);for(let x=0;x<512;x+=128){c.moveTo(x,0);c.lineTo(x+128,128);c.lineTo(x,256)}c.stroke();texture.update();material.diffuseTexture=texture;material.specularColor=new B.Color3(.15,.15,.15);material.backFaceCulling=false;
 for(let i=0;i<p.length;i++){const j=(i+1)%p.length,k=positions.length/3;positions.push(p[i][0],bottom[i],p[i][1],p[j][0],bottom[j],p[j][1],p[j][0],top,p[j][1],p[i][0],top,p[i][1]);indices.push(k,k+2,k+1,k,k+3,k+2);uvs.push(0,0,1,0,1,1,0,1)}
 function mesh(name,pos,ind,mat,uv){const m=new B.Mesh(name,scene),d=new B.VertexData(),n=[];B.VertexData.ComputeNormals(pos,ind,n);d.positions=pos;d.indices=ind;d.normals=n;if(uv)d.uvs=uv;d.applyToMesh(m);m.material=mat;m.freezeWorldMatrix();return m}
 mesh('building-museum-envelope',positions,indices,material,uvs);
 const roofMat=new B.StandardMaterial('museum-roof',scene);roofMat.diffuseColor=B.Color3.FromHexString('#e1e7de');roofMat.backFaceCulling=false;roofMat.specularColor=B.Color3.Black();mesh('building-museum-roof',p.flatMap(q=>[q[0],top+.05,q[1]]),[0,2,1,0,3,2],roofMat);
 const underMat=new B.StandardMaterial('museum-underside',scene);underMat.diffuseColor=B.Color3.FromHexString('#5f7172');underMat.backFaceCulling=false;mesh('building-museum-underside',p.flatMap((q,i)=>[q[0],bottom[i],q[1]]),[0,1,2,0,2,3],underMat);
 const core=B.MeshBuilder.ExtrudePolygon('building-museum-core',{shape:b.collisionOutline.map(q=>V(q[0],0,q[1])),depth:Math.max(...bottom)-Math.min(...hs)+2,sideOrientation:B.Mesh.DOUBLESIDE},scene,earcut);core.position.y=Math.max(...bottom)+1;const coreMat=new B.StandardMaterial('museum-core',scene);coreMat.diffuseColor=B.Color3.FromHexString('#556c70');core.material=coreMat;core.freezeWorldMatrix();b.base=Math.min(...hs);b.top=top;
}
